import{_ as e,o as a,c as i,ao as r}from"./chunks/framework.CjadT2vc.js";const s="/BVDOutbreakSize/previews/PR711/assets/rt.B32B8fUY.png",n="/BVDOutbreakSize/previews/PR711/assets/analysis-270.4TY_kd5P.png",l="/BVDOutbreakSize/previews/PR711/assets/analysis-230.ByMQcJ-C.png",o="/BVDOutbreakSize/previews/PR711/assets/analysis-275.BnDG2oNK.png",d="/BVDOutbreakSize/previews/PR711/assets/infections.MRvHB9xk.png",h="/BVDOutbreakSize/previews/PR711/assets/reported_cases.DCAxJug7.png",g="/BVDOutbreakSize/previews/PR711/assets/rt_streams.C_yJuwK9.png",v=JSON.parse('{"title":"Summary dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"summary.md","filePath":"summary.md","lastUpdated":null}'),p={name:"summary.md"};function u(c,t,m,y,b,x){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="Summary-dashboard" tabindex="-1">Summary dashboard <a class="header-anchor" href="#Summary-dashboard" aria-label="Permalink to &quot;Summary dashboard {#Summary-dashboard}&quot;">​</a></h1><p>A one-page overview of the headline results for readers with limited time. Every number, table and figure on this page is produced by the same model fit as the full <a href="./analysis">Analysis</a> and refreshes whenever the data updates. See the <a href="./analysis">Analysis</a> page for the methods, assumptions and supporting detail behind each result, the <a href="./spatial">Spatial</a> page for the health-zone maps, and the <a href="./sensitivity">Sensitivity</a> page for the forecast validation, the outbreak size implied by each data stream, the comparisons with McCabe et al. and Chamla et al., and the delay and tree-prior sensitivity analyses. Which streams each vintage carries, and which are frozen, is recorded in the inclusion rules in <code>data/README.md</code>.</p><p><strong>Data as of:</strong> 2026-09-15</p><h2 id="Headline-estimates" tabindex="-1">Headline estimates <a class="header-anchor" href="#Headline-estimates" aria-label="Permalink to &quot;Headline estimates {#Headline-estimates}&quot;">​</a></h2><ul><li><p><strong>Cumulative infections:</strong> the outbreak is estimated to have caused 30% 12243–14420, 60% 11365–16083, 90% 10144–19809 infections to date, reported and unreported.</p></li><li><p>Against the 7404 laboratory-confirmed cases by the cut-off that is roughly 1.4–2.7× as many infections, so confirmed cases are estimated to capture only a small share of the outbreak.</p></li><li><p><strong>Outbreak start and age:</strong> the outbreak is estimated to have begun on a start date of 30% 2026-03-17–2026-03-21, 60% 2026-03-14–2026-03-24, 90% 2026-03-08–2026-03-27, an elapsed age to the cut-off of 30% 178–182, 60% 175–185, 90% 172–191 days.</p></li><li><p><strong>Growth rate and doubling time:</strong> the initial growth rate is estimated to have been 30% 0.054–0.069, 60% 0.047–0.08, 90% 0.037–0.098 per day, an initial doubling time of 30% 12.7–10.0, 60% 14.7–8.7, 90% 18.9–7.1 days. The latest growth rate is estimated to be 30% 0.006–0.023, 60% -0.003–0.035, 90% -0.02–0.062 per day, a latest doubling time of 30% 115.2–29.9, 60% -207.7–20.0, 90% -35.3–11.1 days.</p></li><li><p><strong>Reproduction number:</strong> the initial reproduction number is estimated to have been 30% 1.25–1.35, 60% 1.21–1.43, 90% 1.15–1.64 and the latest to be 30% 1.03–1.11, 60% 0.98–1.17, 90% 0.91–1.34.</p></li><li><p><strong>Case-fatality ratio:</strong> the case-fatality ratio is estimated to be 30% 0.44–0.49, 60% 0.41–0.52, 90% 0.36–0.58.</p></li><li><p><strong>By province, infections to date:</strong></p><ul><li><p>Ituri: 30% 8736–10200, 60% 8034–11599, 90% 7128–14394</p></li><li><p>Nord-Kivu: 30% 2860–3502, 60% 2583–4037, 90% 2176–5150</p></li><li><p>Haut-Uele: 30% 469–580, 60% 411–655, 90% 333–820</p></li><li><p>Other provinces: 30% 79–102, 60% 67–118, 90% 53–162</p></li></ul></li><li><p><strong>By province, reproduction number at the cut-off:</strong></p><ul><li><p>Ituri: 30% 0.98–1.07, 60% 0.93–1.13, 90% 0.84–1.32</p></li><li><p>Nord-Kivu: 30% 1.05–1.16, 60% 1.01–1.23, 90% 0.92–1.42</p></li><li><p>Haut-Uele: 30% 0.92–1.04, 60% 0.84–1.12, 90% 0.73–1.3</p></li><li><p>Other provinces: 30% 1.01–1.12, 60% 0.95–1.19, 90% 0.83–1.4</p></li></ul></li><li><p><strong>By province, case-fatality ratio:</strong></p><ul><li><p>Ituri: 30% 39.0–45.9, 60% 35.4–50.0, 90% 29.8–58.5%</p></li><li><p>Nord-Kivu: 30% 50.9–61.2, 60% 46.2–67.8, 90% 39.0–79.8%</p></li><li><p>Haut-Uele: 30% 41.0–46.8, 60% 37.8–50.7, 90% 31.7–59.0%</p></li><li><p>Other provinces: 30% 40.4–47.8, 60% 36.5–53.1, 90% 29.2–61.5%</p></li></ul></li><li><p><strong>Shift from priors:</strong> how far the data has moved each estimate from its prior, in prior interquartile ranges, where a value of one means the posterior median sits one prior interquartile range from the prior median, zero means unchanged, and the sign gives the direction. The fit moves the cumulative infection count by -0.01, the outbreak age by -0.93 and the doubling time by 0.65; the largest move is in the outbreak age.</p></li></ul><h3 id="Outbreak-size-and-timing" tabindex="-1">Outbreak size and timing <a class="header-anchor" href="#Outbreak-size-and-timing" aria-label="Permalink to &quot;Outbreak size and timing {#Outbreak-size-and-timing}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Quantity</th><th style="text-align:right;">Lower 90%</th><th style="text-align:right;">Lower 60%</th><th style="text-align:right;">Lower 30%</th><th style="text-align:right;">Upper 30%</th><th style="text-align:right;">Upper 60%</th><th style="text-align:right;">Upper 90%</th></tr></thead><tbody><tr><td style="text-align:right;">Cumulative infections</td><td style="text-align:right;">10144</td><td style="text-align:right;">11365</td><td style="text-align:right;">12243</td><td style="text-align:right;">14420</td><td style="text-align:right;">16083</td><td style="text-align:right;">19809</td></tr><tr><td style="text-align:right;">Outbreak age (days)</td><td style="text-align:right;">172</td><td style="text-align:right;">175</td><td style="text-align:right;">178</td><td style="text-align:right;">182</td><td style="text-align:right;">185</td><td style="text-align:right;">191</td></tr></tbody></table><h3 id="Growth-and-severity" tabindex="-1">Growth and severity <a class="header-anchor" href="#Growth-and-severity" aria-label="Permalink to &quot;Growth and severity {#Growth-and-severity}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Quantity</th><th style="text-align:right;">Lower 90%</th><th style="text-align:right;">Lower 60%</th><th style="text-align:right;">Lower 30%</th><th style="text-align:right;">Upper 30%</th><th style="text-align:right;">Upper 60%</th><th style="text-align:right;">Upper 90%</th></tr></thead><tbody><tr><td style="text-align:right;">Initial reproduction number</td><td style="text-align:right;">1.15</td><td style="text-align:right;">1.21</td><td style="text-align:right;">1.25</td><td style="text-align:right;">1.35</td><td style="text-align:right;">1.43</td><td style="text-align:right;">1.64</td></tr><tr><td style="text-align:right;">Latest reproduction number</td><td style="text-align:right;">0.91</td><td style="text-align:right;">0.98</td><td style="text-align:right;">1.03</td><td style="text-align:right;">1.11</td><td style="text-align:right;">1.17</td><td style="text-align:right;">1.34</td></tr><tr><td style="text-align:right;">Latest growth rate (per day)</td><td style="text-align:right;">-0.02</td><td style="text-align:right;">0</td><td style="text-align:right;">0.01</td><td style="text-align:right;">0.02</td><td style="text-align:right;">0.03</td><td style="text-align:right;">0.06</td></tr><tr><td style="text-align:right;">Latest doubling time (days)</td><td style="text-align:right;">-35.25</td><td style="text-align:right;">-207.73</td><td style="text-align:right;">115.16</td><td style="text-align:right;">29.88</td><td style="text-align:right;">20.03</td><td style="text-align:right;">11.12</td></tr><tr><td style="text-align:right;">Case-fatality ratio</td><td style="text-align:right;">0.36</td><td style="text-align:right;">0.41</td><td style="text-align:right;">0.44</td><td style="text-align:right;">0.49</td><td style="text-align:right;">0.52</td><td style="text-align:right;">0.58</td></tr></tbody></table><p>All intervals are equal-tailed 30%, 60% and 90% credible intervals from the joint posterior.</p><h3 id="By-province" tabindex="-1">By province <a class="header-anchor" href="#By-province" aria-label="Permalink to &quot;By province {#By-province}&quot;">​</a></h3><p>The model runs one renewal equation per province and fits the national streams against the summed provinces, so the national count above is the sum of the three below. Each cell is a median with a 90% credible interval. The reproduction number and the relative ascertainment are read together, because the per-province case data identify only their product.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Province</th><th style="text-align:right;">Reproduction number</th><th style="text-align:right;">Cumulative infections</th><th style="text-align:right;">Share of infections (%)</th><th style="text-align:right;">Relative ascertainment</th></tr></thead><tbody><tr><td style="text-align:right;">Ituri</td><td style="text-align:right;">1.02 (0.84–1.32)</td><td style="text-align:right;">9405 (7128–14394)</td><td style="text-align:right;">71.9 (63.3–77.0)</td><td style="text-align:right;">1.06 (0.9–1.38)</td></tr><tr><td style="text-align:right;">Nord-Kivu</td><td style="text-align:right;">1.1 (0.92–1.42)</td><td style="text-align:right;">3140 (2176–5150)</td><td style="text-align:right;">23.4 (18.6–31.5)</td><td style="text-align:right;">0.93 (0.69–1.11)</td></tr><tr><td style="text-align:right;">Haut-Uele</td><td style="text-align:right;">0.98 (0.73–1.3)</td><td style="text-align:right;">521 (333–820)</td><td style="text-align:right;">3.8 (2.8–5.1)</td><td style="text-align:right;">1.02 (0.86–1.29)</td></tr><tr><td style="text-align:right;">Other provinces</td><td style="text-align:right;">1.06 (0.83–1.4)</td><td style="text-align:right;">89 (53–162)</td><td style="text-align:right;">0.7 (0.4–1.1)</td><td style="text-align:right;">0.99 (0.76–1.25)</td></tr></tbody></table><h2 id="Estimated-reproduction-number" tabindex="-1">Estimated reproduction number <a class="header-anchor" href="#Estimated-reproduction-number" aria-label="Permalink to &quot;Estimated reproduction number {#Estimated-reproduction-number}&quot;">​</a></h2><p>The time-varying reproduction number R(t), the average number of further infections caused by each infection. A value above one means the outbreak is growing.</p><p><img src="'+s+'" alt=""></p><p>The same trajectory by province, with the national one in grey behind each panel. A panel tracking grey says that province moves with the national trend.</p><p><img src="'+n+'" alt=""></p><h2 id="Provinces" tabindex="-1">Provinces <a class="header-anchor" href="#Provinces" aria-label="Permalink to &quot;Provinces {#Provinces}&quot;">​</a></h2><p>Modelled infections by province, and each province&#39;s size, reproduction number and relative case ascertainment.</p><p><img src="'+l+'" alt=""></p><p><img src="'+o+'" alt=""></p><h2 id="Infections-over-time" tabindex="-1">Infections over time <a class="header-anchor" href="#Infections-over-time" aria-label="Permalink to &quot;Infections over time {#Infections-over-time}&quot;">​</a></h2><p>Modelled cumulative infections, symptom onsets and deaths. These are the underlying outbreak, upstream of the testing and reporting that produce the observed counts, so they are larger than the reported cases.</p><p><img src="'+d+'" alt=""></p><h2 id="Reported-cases:-model-versus-observed" tabindex="-1">Reported cases: model versus observed <a class="header-anchor" href="#Reported-cases:-model-versus-observed" aria-label="Permalink to &quot;Reported cases: model versus observed {#Reported-cases:-model-versus-observed}&quot;">​</a></h2><p>Modelled reported cases against the observed reported cases over time, a check that the fit reproduces what was seen on the ground.</p><p><img src="'+h+'" alt=""></p><h2 id="Reproduction-number-by-data-stream" tabindex="-1">Reproduction number by data stream <a class="header-anchor" href="#Reproduction-number-by-data-stream" aria-label="Permalink to &quot;Reproduction number by data stream {#Reproduction-number-by-data-stream}&quot;">​</a></h2><p>The reproduction number each data stream implies on its own, fitted to that stream alone. Agreement between the streams supports the joint estimate; disagreement shows where they pull in different directions.</p><p><img src="'+g+'" alt=""></p><h2 id="Health-zones" tabindex="-1">Health zones <a class="header-anchor" href="#Health-zones" aria-label="Permalink to &quot;Health zones {#Health-zones}&quot;">​</a></h2><p>Each patch&#39;s infections split across its health zones, the zone maps and the interactive zone map are on the <a href="./spatial">Spatial</a> page.</p><hr><p>For the full results, methods and code see the <a href="./analysis">Analysis</a> page and the <a href="https://github.com/epiforecasts/BVDOutbreakSize" target="_blank" rel="noreferrer">epiforecasts/BVDOutbreakSize</a> repository.</p>',35)])])}const k=e(p,[["render",u]]);export{v as __pageData,k as default};
